import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"双调·折桂令湖上寒食","description":"","frontmatter":{"title":"双调·折桂令湖上寒食","date":"2026-11-11T00:00:00.000Z","seq":14,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/双调·折桂令湖上寒食.md","filePath":"blogs/元曲·张可久/双调·折桂令湖上寒食.md"}'),o={name:"blogs/元曲·张可久/双调·折桂令湖上寒食.md"};function c(l,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="双调·折桂令湖上寒食" tabindex="-1">双调·折桂令湖上寒食 <a class="header-anchor" href="#双调·折桂令湖上寒食" aria-label="Permalink to &quot;双调·折桂令湖上寒食&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">雨霏霏店舍无烟，榆荚飞钱，柳线搓绵。</p><p class="poem-stanza">绿水人家，残花院落，美女秋千。</p><p class="poem-stanza">沽酒春衣自典，思家客子谁怜？第一桥边，恋住流莺，不信啼鹃。</p><p class="poem-stanza">湖上道院鹤飞来一缕青霞，笑富贵飞蚊，名利争蜗。</p><p class="poem-stanza">古砚玄香，名琴绿绮，土釜黄芽。</p><p class="poem-stanza">双井先春采茶，孤山带月锄花。</p><p class="poem-stanza">童子谁家？贪看西湖，懒诵南华。</p><p class="poem-stanza">酒边即事莺莺燕燕相亲，幸有名园，著我闲身。</p><p class="poem-stanza">竹点诗痕，花消酒困，柳拂歌尘。</p><p class="poem-stanza">锦帐里团香弄粉，画楼前访雨寻云。</p><p class="poem-stanza">不负青春，谁共佳人，相约黄昏？避暑醉题俯沧波楼观烟霞，胜览方舆，独占繁华。</p><p class="poem-stanza">彩舰轻帘，银鞍骏马，翠袖娇娃。</p><p class="poem-stanza">十里香风酒家，一川凉雨荷花。</p><p class="poem-stanza">醉墨涂鸦，题遍红楼，倒裹乌纱。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
